#!/usr/bin/env python3
"""Teach the Android builder about ImportShim - on the **SAF recipe** path.

effectcraft's Activity comes from the recipe entry ``"effectcraft": {"activity":
"EffectCraftActivity", ...}`` in ``lib/build-common.sh``, so it is generated by the ``if saf:``
branch, not by the generated-launcher ``else:`` branch and not by ``adapters/``.

Three edits, each count-verified:

A. Define the shim's filters next to ``intent_filter_value``.
B. Append a second ``[[package.metadata.android.application.activity]]`` (name ``.ImportShim``)
   after the main activity's ``meta_data`` block, carrying VIEW/SEND filters.
C. Write ``ImportShim.java`` into the generated Java source tree next to ``SafActivity``.

Run from the builder checkout root before ``bash lib/build-common.sh``.
"""
from __future__ import annotations

import sys
from pathlib import Path

A_OLD = "    intent_filter_value = file_associations.intent_filter_toml(app)\n    if saf:\n"
A_NEW = '''    intent_filter_value = file_associations.intent_filter_toml(app)
    # ImportShim: headless trampoline so "Open with"/"Share to" can hand us a document without a
    # full SAF bridge. Byte-for-byte, its filters are the same table the app itself advertises.
    _shim_exts = file_associations.ASSOCIATIONS.get(app, [])
    _shim_data = file_associations._by_extension_data(_shim_exts, typed=True)
    shim_filters = (
        # Catch-all: content URIs look like /document/1000012345 with no extension, so every
        # pathPattern filter misses. This one takes any content/file document.
        '{ actions = ["android.intent.action.VIEW"], '
        'categories = ["android.intent.category.DEFAULT", "android.intent.category.BROWSABLE"], '
        'data = [{ scheme = "content", host = "*", mime_type = "*/*" }, '
        '{ scheme = "file", mime_type = "*/*" }] }, '
        # Precise by-extension match, kept for providers that do keep the name in the path.
        '{ actions = ["android.intent.action.VIEW"], '
        'categories = ["android.intent.category.DEFAULT"], data = [' + _shim_data + '] }, '
        # Share sheet: one typed filter and one data-less filter (the latter is what matches an
        # ACTION_SEND whose type is empty).
        '{ actions = ["android.intent.action.SEND", "android.intent.action.SEND_MULTIPLE"], '
        'categories = ["android.intent.category.DEFAULT"], data = [{ mime_type = "*/*" }] }, '
        '{ actions = ["android.intent.action.SEND", "android.intent.action.SEND_MULTIPLE"], '
        'categories = ["android.intent.category.DEFAULT"] }'
    )
    if saf:
'''

B_OLD = '''[[package.metadata.android.application.activity.meta_data]]
name = "android.app.lib_name"
value = "{app}_android"
\'\'\'
'''
B_NEW = '''[[package.metadata.android.application.activity.meta_data]]
name = "android.app.lib_name"
value = "{app}_android"

# ImportShim: headless trampoline for Open with / Share to (templates/android/ImportShim.java).
[[package.metadata.android.application.activity]]
name = ".ImportShim"
label = "{title}"
theme = "@android:style/Theme.NoDisplay"
exclude_from_recents = true
exported = true
intent_filter = [{shim_filters}]
\'\'\'
'''

C_OLD = '''        (java_dir / f"{saf['activity']}.java").write_text(java_src)
'''
C_NEW = '''        (java_dir / f"{saf['activity']}.java").write_text(java_src)
        # ImportShim.java ships in templates/android and is compiled alongside the SAF activity.
        _shim_src = Path(__import__("os").environ["IMPORT_SHIM_JAVA"]).read_text(encoding="utf-8")
        (java_dir / "ImportShim.java").write_text(
            _shim_src.replace("__PACKAGE__", pkg), encoding="utf-8"
        )
'''


def main() -> int:
    root = Path(sys.argv[1] if len(sys.argv) > 1 else "artcraft").resolve()
    sh = root / "lib" / "build-common.sh"
    src = sh.read_text(encoding="utf-8")
    if "ImportShim" in src:
        print("builder already patched")
        return 0
    for name, old in (("A", A_OLD), ("B", B_OLD), ("C", C_OLD)):
        if src.count(old) != 1:
            print(f"FAIL {name}: expected 1, found {src.count(old)}", file=sys.stderr)
            return 1
    src = src.replace(A_OLD, A_NEW, 1).replace(B_OLD, B_NEW, 1).replace(C_OLD, C_NEW, 1)
    sh.write_text(src, encoding="utf-8")
    print("builder patched on the saf path: ImportShim activity + Java source")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
